  1→import * as os from "node:os";
  2→import * as path from "node:path";
  3→import * as clack from "@clack/prompts";
  4→import type { Config } from "../config/config.js";
  5→import type { ConfiguredChannelAction, ChannelId, ChannelStatus } from "./types.js";
  6→import { CHANNEL_META } from "./types.js";
  7→import { guardCancel, ok, c } from "./helpers.js";
  8→
  9→export function getChannelStatuses(config: Config): ChannelStatus[] {
 10→  const statuses: ChannelStatus[] = [];
 11→
 12→  for (const [id, meta] of Object.entries(CHANNEL_META) as [ChannelId, typeof CHANNEL_META[ChannelId]][]) {
 13→    const ch = config.channels[id] as Record<string, unknown> | undefined;
 14→    const enabled = ch?.enabled === true;
 15→    const configured = !!ch && Object.keys(ch).length > 1;
 16→
 17→    let hint: string | undefined;
 18→    if (id === "telegram" && ch?.botToken && typeof ch.botToken === "string" && ch.botToken !== "YOUR_BOT_TOKEN_HERE") {
 19→      hint = `Chat ID: ${ch.chatId}`;
 20→    }
 21→    if (id === "discord" && ch?.guildId) {
 22→      hint = `Guild: ${ch.guildId}`;
 23→    }
 24→
 25→    statuses.push({ id, label: meta.label, configured, enabled, hint });
 26→  }
 27→
 28→  return statuses;
 29→}
 30→
 31→export function noteChannelStatus(config: Config): void {
 32→  const statuses = getChannelStatuses(config);
 33→  const lines = statuses.map((s) => {
 34→    const status = s.enabled ? "enabled" : s.configured ? "disabled" : "not configured";
 35→    const hintStr = s.hint ? ` — ${s.hint}` : "";
 36→    return `  ${s.label}: ${status}${hintStr}`;
 37→  });
 38→
 39→  console.log("");
 40→  console.log(`${c.bold}  Channel status${c.reset}`);
 41→  for (const line of lines) console.log(line);
 42→  console.log("");
 43→}
 44→
 45→async function promptConfiguredAction(label: string): Promise<ConfiguredChannelAction> {
 46→  return guardCancel(
 47→    await clack.select({
 48→      message: `${label} already configured. What do you want to do?`,
 49→      options: [
 50→        { value: "modify" as const, label: "Modify settings" },
 51→        { value: "disable" as const, label: "Disable bot" },
 52→        { value: "delete" as const, label: "Delete config" },
 53→        { value: "skip" as const, label: "Skip (leave as-is)" },
 54→      ],
 55→      initialValue: "modify" as const,
 56→    }),
 57→  );
 58→}
 59→
 60→async function configureViaPlugin(channelId: ChannelId): Promise<void> {
 61→  const pluginMap: Record<ChannelId, { importPath: string; name: string }> = {
 62→    telegram: { importPath: '../../plugins/telegram/index.js', name: '@openacp/telegram' },
 63→    discord: { importPath: '../../plugins/discord/index.js', name: '@openacp/discord' },
 64→  };
 65→
 66→  const pluginInfo = pluginMap[channelId];
 67→  if (!pluginInfo) return;
 68→
 69→  const { SettingsManager } = await import('../plugin/settings-manager.js');
 70→  const { createInstallContext } = await import('../plugin/install-context.js');
 71→  const basePath = path.join(os.homedir(), '.openacp', 'plugins');
 72→  const settingsManager = new SettingsManager(basePath);
 73→
 74→  const pluginModule = await import(pluginInfo.importPath);
 75→  const plugin = pluginModule.default;
 76→
 77→  if (plugin?.configure) {
 78→    const ctx = createInstallContext({
 79→      pluginName: plugin.name,
 80→      settingsManager,
 81→      basePath,
 82→    });
 83→    await plugin.configure(ctx);
 84→  }
 85→}
 86→
 87→export async function configureChannels(config: Config): Promise<{ config: Config; changed: boolean }> {
 88→  const next = structuredClone(config);
 89→  let changed = false;
 90→
 91→  noteChannelStatus(next);
 92→
 93→  while (true) {
 94→    const statuses = getChannelStatuses(next);
 95→    const options = statuses.map((s) => {
 96→      const status = s.enabled ? "enabled" : s.configured ? "disabled" : "not configured";
 97→      return {
 98→        value: s.id,
 99→        label: `${s.label} (${CHANNEL_META[s.id].method})`,
100→        hint: status + (s.hint ? ` · ${s.hint}` : ""),
101→      };
102→    });
103→
104→    const choice = guardCancel(
105→      await clack.select({
106→        message: "Select a channel",
107→        options: [
108→          ...options,
109→          { value: "__done__" as const, label: "Finished" },
110→        ],
111→      }),
112→    );
113→
114→    if (choice === "__done__") break;
115→
116→    const channelId = choice as ChannelId;
117→    const meta = CHANNEL_META[channelId];
118→    const existing = next.channels[channelId] as Record<string, unknown> | undefined;
119→    const isConfigured = !!existing && Object.keys(existing).length > 1;
120→
121→    if (isConfigured) {
122→      const action = await promptConfiguredAction(meta.label);
123→
124→      if (action === "skip") continue;
125→      if (action === "disable") {
126→        (next.channels[channelId] as Record<string, unknown>).enabled = false;
127→        changed = true;
128→        console.log(ok(`${meta.label} disabled`));
129→        continue;
130→      }
131→      if (action === "delete") {
132→        const confirmed = guardCancel(
133→          await clack.confirm({
134→            message: `Delete ${meta.label} config? This cannot be undone.`,
135→            initialValue: false,
136→          }),
137→        );
