  const settingsManager = new SettingsManager(basePath);

  const pluginModule = await importer();
  const plugin = pluginModule.default;

  if (plugin?.configure) {
    const ctx = createInstallContext({
      pluginName: plugin.name,
      settingsManager,
      basePath,
